function getUint32(buffer, startPos){
    return buffer[startPos] | buffer[startPos+1] << 8 | buffer[startPos+2] << 16 | buffer[startPos+3] << 24;
}

function getUint16(buffer, startPos){
    return buffer[startPos] | buffer[startPos+1] << 8;
}

function getUint8(buffer, startPos){
    return buffer[startPos];
}

function getFloat32(buffer, startPos){
    return Bytes2Float32(getUint32(buffer, startPos));
}

function Bytes2Float32(bytes) {
    var sign = (bytes & 0x80000000) ? -1 : 1;
    var exponent = ((bytes >> 23) & 0xFF) - 127;
    var significand = (bytes & ~(-1 << 23));

    if (exponent == 128) 
        return sign * ((significand) ? Number.NaN : Number.POSITIVE_INFINITY);

    if (exponent == -127) {
        if (significand == 0) return sign * 0.0;
        exponent = -126;
        significand /= (1 << 22);
    } else significand = (significand | (1 << 23)) / (1 << 23);

    return sign * significand * Math.pow(2, exponent);
}

